def segments(lon_min: float, lon_max: float):
    """Coastline polylines clipped to a longitude window, wrapping if needed.

    A Pacific-centred map runs from 100E to 300E, which crosses the antimeridian
    where the source data flips from +180 to -180. Re-wrapping each vertex into
    the requested frame and then splitting wherever a segment jumps more than
    180 degrees keeps Asia and the Americas from being joined by a line straight
    across the plot.
    """
    out = []
    for line in COASTLINE:
        current: list[tuple[float, float]] = []
        previous = None
        for lon, lat in line:
            x = lon
            while x < lon_min:
                x += 360.0
            while x > lon_min + 360.0:
                x -= 360.0
            if previous is not None and abs(x - previous) > 180.0:
                if len(current) > 1:
                    out.append(current)
                current = []
            current.append((x, lat))
            previous = x
        if len(current) > 1:
            out.append(current)
    clipped = []
    for line in out:
        if any(lon_min - 5 <= x <= lon_max + 5 for x, _ in line):
            clipped.append(tuple(line))
    return tuple(clipped)
